// @ts-nocheck – scaffold generated by scripts/build-manifest.mjs; props mirror the manifest's Figma properties.
// Fill FIGMA_NODE_URL once the kit exists, then run `pnpm figma:connect` to publish.
import figma from '@figma/code-connect';
import { PasswordField } from '@davinci-ai/react';

const FIGMA_NODE_URL = 'FIGMA_NODE_URL'; // e.g. https://www.figma.com/design/<file>?node-id=<id>  (Inputs/PasswordField)

figma.connect(PasswordField, FIGMA_NODE_URL, {
  props: {
    prefix: figma.string('prefix'),
    size: figma.enum('size', { 'sm': 'sm', 'md': 'md', 'lg': 'lg' }),
    label: figma.string('label'),
    description: figma.string('description'),
    errorMessage: figma.string('errorMessage'),
    placeholder: figma.string('placeholder'),
  },
  example: ({ label, prefix, size, description, errorMessage, placeholder }) => (
    <PasswordField prefix={prefix} size={size} description={description} errorMessage={errorMessage} placeholder={placeholder}>{label}</PasswordField>
  ),
});
